#include <vector>
#include <algorithm>

class Solution {
public:
    bool canConstructGraph(std::vector<int>& degrees) {
        std::vector<int> deg;
        for (int d : degrees) {
            if (d > 0) deg.push_back(d);
        }

        while (!deg.empty()) {
            std::sort(deg.begin(), deg.end(), std::greater<int>());
            int d = deg.front();
            deg.erase(deg.begin());

            if (d > (int)deg.size()) return false;
            for (int i = 0; i < d; ++i) {
                deg[i]--;
                if (deg[i] < 0) return false;
            }
            std::vector<int> next_deg;
            for (int x : deg) {
                if (x > 0) next_deg.push_back(x);
            }
            deg = std::move(next_deg);
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean canConstructGraph(int[] degrees) {
        List<Integer> deg = new ArrayList<>();
        for (int d : degrees) {
            if (d > 0) deg.add(d);
        }

        while (!deg.isEmpty()) {
            deg.sort(Collections.reverseOrder());
            int d = deg.remove(0);
            if (d > deg.size()) return false;
            for (int i = 0; i < d; i++) {
                int val = deg.get(i) - 1;
                if (val < 0) return false;
                deg.set(i, val);
            }
            deg.removeIf(x -> x == 0);
        }
        return true;
    }
}

var canConstructGraph = function(degrees) {
    let deg = degrees.filter(d => d > 0);

    while (deg.length > 0) {
        deg.sort((a, b) => b - a);
        const d = deg.shift();
        if (d > deg.length) return false;
        for (let i = 0; i < d; i++) {
            deg[i]--;
            if (deg[i] < 0) return false;
        }
        deg = deg.filter(x => x > 0);
    }
    return true;
};
